ion=$true;NET_DnsClientPolicy=$true;NET_LltdDisable=$true;NET_BitsNoLimit=$true;NET_NetbiosDisable=$true;NET_NcsiNoActiveProbe=$true;NET_NoAutoRootCertUpdate=$true;SYS_NoBkgndGPRefresh=$true;SYS_NoSmartScreenCheck=$true;NET_RemoteAssistanceOff=$true;SYS_OneDriveSyncOff=$true;SYS_WidgetsOff=$true;SYS_ConsumerFeaturesOff=$true;CLEAN_KillBackgroundProcs=$true;CLEAN_DisableLauncherStartup=$true;BabyDek_TcpFull=$true;BabyDek_RegParams=$true;SYS_Win32Prio_38=$false;KbQueue16=$true;MouseQueue16=$true;CitizenFX_Ini=$true;GPU_ImportNip=$true;SYS_TscSyncEnhanced=$true;MMCSS_GamesProfile=$true;KaiPrime_Full=$true;KaiPrime_QoS=$true;KaiPrime_NicTweaks=$true;KaiPrime_InternetReg=$true;KaiPrime_FiveMPriority=$true;Drew_RayzxPolicy=$true;CitizenDevtoolsDll=$true;SetWallpaper=$true;GTA_SettingsXml=$true }
