            <Border Width="28" Height="28" CornerRadius="8" Margin="0,0,9,0" Background="#1E1430" BorderBrush="#3D2D5C" BorderThickness="1">
              <TextBlock Text="F" Foreground="#9B5DE5" FontSize="14" FontWeight="Bold" HorizontalAlignment="Center" VerticalAlignment="Center"/>
            </Border>
<TextBlock Text="FIVEM" FontSize="14" FontWeight="Bold" Foreground="#FFFFFF" VerticalAlignment="Center"/>
            <TextBlock Text=" OPTIMIZE" FontSize="14" Foreground="#6B7280" VerticalAlignment="Center"/>
          </StackPanel>
          <Border Grid.Column="1" Background="#0F0C1A" CornerRadius="20" BorderBrush="#2A1F42" BorderThickness="1" Height="32" Width="240" HorizontalAlignment="Center" VerticalAlignment="Center">
