function Run-FiveMPerfOptions{
    Set-CurrentTask "FiveM Priority + CEF Tweaks (IFEO)"
    # From fivem-tweaks.ps1: IFEO CpuPriorityClass=3 for both executables + CEFHardwareAcceleration=0
    foreach($exeName in @("FiveM_GTAProcess.exe","FiveM.exe")){
        $p="HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\$exeName\PerfOptions"
        Save-Orig "GM_FiveMPerfOptions_$exeName" $p "CpuPriorityClass"
        New-Item $p -Force -EA SilentlyContinue | Out-Null
        Set-RegValue $p "CpuPriorityClass" 3|Out-Null
        Add-Log "$exeName CpuPriorityClass set to 3 (AboveNormal) via IFEO" "#9B5DE5"
    }
    $p2="HKCU:\Software\CitizenFX\FiveM"
