        $count=0
        foreach($a in $la){ Enable-NetAdapterRss -Name $a.Name -EA SilentlyContinue; $count++ }
        if($count -gt 0){ Add-Log "RSS enabled on $count wired adapter(s)" "#9B5DE5" } else { Add-Log "No wired adapter detected - skipped" "#6B7280" }
