    try{
        $paths=Get-GpuInstancePaths "NVIDIA"
        $applied = 0
        foreach($path in $paths){
            Save-Orig "GPU_NvidiaMSIMode_$([math]::Abs($path.GetHashCode()))" $path "MSISupported"
