        if($applied -gt 0){
            Add-Log "NVIDIA MSI mode enabled ($applied instance(s))" "#9B5DE5"
        } else {
            Add-Log "NVIDIA MSI mode could not be enabled (hardware may not support it)" "#EF4444"
