function Run-TimerRes{
    Set-CurrentTask "System Timer Resolution -> 0.5ms (STR Service)"
    try{
        if(-not ("Win32TimerRes" -as [type])){
            Add-Type -Namespace Win32TimerResNS -Name Win32TimerRes -MemberDefinition @"
[DllImport("ntdll.dll")] public static extern int NtSetTimerResolution(uint DesiredResolution, bool SetResolution, ref uint CurrentResolution);
"@
        }
        [uint32]$cur=0
        [Win32TimerResNS.Win32TimerRes]::NtSetTimerResolution(5000,$true,[ref]$cur)|Out-Null
        Add-Log "Timer resolution set to ~0.5ms (in-session)" "#9B5DE5"

        # Persistent service from timer-resolution-str.ps1
        $csPath = "$env:ProgramData\SetTimerResolutionService.cs"
        $exePath = "$env:ProgramData\SetTimerResolutionService.exe"
        $cs = @'
using System;using System.Runtime.InteropServices;using System.ServiceProcess;using System.ComponentModel;using System.Configuration.Install;using System.Collections.Generic;using System.Reflection;using System.IO;using System.Management;using System.Threading;using System.Diagnostics;
[assembly: AssemblyVersion("2.1")][assembly: AssemblyProduct("Set Timer Resolution service")]
namespace WindowsService{
class WindowsService:ServiceBase{
public WindowsService(){this.ServiceName="Set Timer Resolution Service";this.EventLog.Log="Application";this.CanStop=true;this.CanHandlePowerEvent=false;this.CanHandleSessionChangeEvent=false;this.CanPauseAndContinue=false;this.CanShutdown=false;}
static void Main(){ServiceBase.Run(new WindowsService());}
protected override void OnStart(string[] args){base.OnStart(args);ReadProcessList();NtQueryTimerResolution(out this.MinimumResolution,out this.MaximumResolution,out this.DefaultResolution);if(null==this.ProcessesNames){SetMaximumResolution();return;}if(0==this.ProcessesNames.Count){return;}this.ProcessStartDelegate=new OnProcessStart(this.ProcessStarted);try{String query=String.Format("SELECT * FROM __InstanceCreationEvent WITHIN 0.5 WHERE (TargetInstance isa \"Win32_Process\") AND (TargetInstance.Name=\"{0}\")",String.Join("\" OR TargetInstance.Name=\"",this.ProcessesNames));this.startWatch=new ManagementEventWatcher(query);this.startWatch.EventArrived+=this.startWatch_EventArrived;this.startWatch.Start();}catch{}}
protected override void OnStop(){if(null!=this.startWatch){this.startWatch.Stop();}base.OnStop();}
ManagementEventWatcher startWatch;void startWatch_EventArrived(object sender,EventArrivedEventArgs e){try{ManagementBaseObject process=(ManagementBaseObject)e.NewEvent.Properties["TargetInstance"].Value;UInt32 processId=(UInt32)process.Properties["ProcessId"].Value;this.ProcessStartDelegate.BeginInvoke(processId,null,null);}catch{}}
[DllImport("kernel32.dll",SetLastError=true)]static extern Int32 WaitForSingleObject(IntPtr Handle,Int32 Milliseconds);
[DllImport("kernel32.dll",SetLastError=true)]static extern IntPtr OpenProcess(UInt32 DesiredAccess,Int32 InheritHandle,UInt32 ProcessId);
[DllImport("kernel32.dll",SetLastError=true)]static extern Int32 CloseHandle(IntPtr Handle);
const UInt32 SYNCHRONIZE=0x00100000;delegate void OnProcessStart(UInt32 processId);OnProcessStart ProcessStartDelegate=null;
void ProcessStarted(UInt32 processId){SetMaximumResolution();IntPtr processHandle=IntPtr.Zero;try{processHandle=OpenProcess(SYNCHRONIZE,0,processId);if(processHandle!=IntPtr.Zero)WaitForSingleObject(processHandle,-1);}catch{}finally{if(processHandle!=IntPtr.Zero)CloseHandle(processHandle);}SetDefaultResolution();}
List<String> ProcessesNames=null;void ReadProcessList(){String iniFilePath=Assembly.GetExecutingAssembly().Location+".ini";if(File.Exists(iniFilePath)){this.ProcessesNames=new List<String>();foreach(var line in File.ReadAllLines(iniFilePath)){foreach(var name in line.Split(new char[]{',',' ',';'},StringSplitOptions.RemoveEmptyEntries)){String lwr_name=name.ToLower();if(!lwr_name.EndsWith(".exe"))lwr_name+=".exe";if(!this.ProcessesNames.Contains(lwr_name))this.ProcessesNames.Add(lwr_name);}}}}
[DllImport("ntdll.dll",SetLastError=true)]static extern int NtSetTimerResolution(uint DesiredResolution,bool SetResolution,out uint CurrentResolution);
[DllImport("ntdll.dll",SetLastError=true)]static extern int NtQueryTimerResolution(out uint MinimumResolution,out uint MaximumResolution,out uint ActualResolution);
uint DefaultResolution=0,MinimumResolution=0,MaximumResolution=0;long processCounter=0;
void SetMaximumResolution(){if(Interlocked.Increment(ref this.processCounter)<=1){uint actual=0;NtSetTimerResolution(this.MaximumResolution,true,out actual);}}
void SetDefaultResolution(){if(Interlocked.Decrement(ref this.processCounter)<1){uint actual=0;NtSetTimerResolution(this.DefaultResolution,true,out actual);}}
}
[RunInstaller(true)]public class WindowsServiceInstaller:Installer{public WindowsServiceInstaller(){ServiceProcessInstaller spi=new ServiceProcessInstaller();ServiceInstaller si=new ServiceInstaller();spi.Account=ServiceAccount.LocalSystem;spi.Username=null;spi.Password=null;si.DisplayName="Set Timer Resolution Service";si.StartType=ServiceStartMode.Automatic;si.ServiceName="Set Timer Resolution Service";this.Installers.Add(spi);this.Installers.Add(si);}}
}
'@
        Set-Content -Path $csPath -Value $cs -Force -EA SilentlyContinue
        if (Get-Service -Name "STR" -EA SilentlyContinue) { Stop-Service -Name "STR" -Force -EA SilentlyContinue; sc.exe delete "STR" 2>$null | Out-Null }
        if (Get-Service -Name "Set Timer Resolution Service" -EA SilentlyContinue) { Stop-Service -Name "Set Timer Resolution Service" -Force -EA SilentlyContinue }
        $csc = "C:\Windows\Microsoft.NET\Framework64\v4.0.30319\csc.exe"
        if(Test-Path $csc){
            & $csc -nologo -out:"$exePath" "$csPath" 2>$null | Out-Null
            Remove-Item $csPath -EA SilentlyContinue
            if (-not (Get-Service -Name "Set Timer Resolution Service" -EA SilentlyContinue)) {
                New-Service -Name "Set Timer Resolution Service" -DisplayName "Set Timer Resolution Service" -BinaryPathName $exePath -EA SilentlyContinue | Out-Null
            }
            Set-Service -Name "Set Timer Resolution Service" -StartupType Automatic -EA SilentlyContinue
            Start-Service -Name "Set Timer Resolution Service" -EA SilentlyContinue
            Add-Log "Set Timer Resolution Service installed/started" "#9B5DE5"
        } else {
            Add-Log "csc.exe not found - skipped persistent STR service (in-session still applied)" "#F59E0B"
            Remove-Item $csPath -EA SilentlyContinue
        }
        $kPath = 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\kernel'
        Save-Orig "SYS_TimerRes_Global" $kPath "GlobalTimerResolutionRequests"
        Set-ItemProperty -Path $kPath -Name 'GlobalTimerResolutionRequests' -Value 1 -Type DWord -Force -EA SilentlyContinue
        Add-Log "GlobalTimerResolutionRequests = 1" "#9B5DE5"
        $Global:AppliedKeys["SYS_TimerRes"]=$true
    } catch { Add-Log "Timer resolution tweak failed: $_" "#EF4444" }
}
