# ========== Integrated from BabyDek / 32.reg / keyboard.reg / mouse.reg / 8k.cmd / KaiPrime / CitizenFX.ini ==========
function Run-BabyDekTcpFull {
    Set-CurrentTask "BabyDek TCP Full Stack (27 cmds)"
    $tcpCmds = @(
        "netsh int tcp set global rss=enabled",
        "netsh int tcp set global dca=enabled",
        "netsh int tcp set global netdma=enabled",
        "netsh int tcp set global chimney=disabled",
        "netsh int tcp set global rsc=disabled",
        "netsh int tcp set global ecncapability=disabled",
        "netsh int tcp set global timestamps=disabled",
        "netsh int tcp set global nonsackrttresiliency=disabled",
        "netsh int tcp set global autotuninglevel=disabled",
        "netsh int tcp set global fastopen=enabled",
        "netsh int tcp set global fastopenfallback=enabled",
        "netsh int tcp set global maxsynretransmissions=2",
        "netsh int tcp set global initialrto=2000",
        "netsh int tcp set global mincto=0",
        "netsh int tcp set global congestionprovider=ctcp",
        "netsh int tcp set supplemental congestionprovider=ctcp",
        "netsh int tcp set heuristics disabled",
        "netsh int ipv4 set glob defaultcurhoplimit=64",
        "netsh int ipv6 set glob defaultcurhoplimit=64",
        "netsh int ip set global taskoffload=enabled",
        "netsh int ip set global multicastforwarding=disabled",
        "netsh int ip set global reassemblylimit=0",
        "netsh int udp set global uro=disabled",
        "netsh int tcp set global memoryprofile=normal",
        "netsh int ipv6 set global randomizeidentifiers=disabled",
        "netsh int ipv6 set privacy state=disabled"
    )
    $ok=0
    foreach($cmd in $tcpCmds){
        try { Invoke-Expression "$cmd 2>&1" | Out-Null; $ok++ } catch {}
    }
    Add-Log "BabyDek TCP: $ok/$($tcpCmds.Count) commands applied" "#9B5DE5"
    $Global:AppliedKeys["BabyDek_TcpFull"]=$true
}

function Run-BabyDekRegParams {
    Set-CurrentTask "BabyDek TCP Registry Parameters"
    $pPath = "HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters"
    $pVals = @{
        "TcpAckFrequency"=1; "TcpDelAckTicks"=0; "TCPNoDelay"=1
        "TcpWindowSize"=65535; "GlobalMaxTcpWindowSize"=65535
        "SackOpts"=1; "Tcp1323Opts"=1; "TcpMaxDataRetransmissions"=3
        "TCPTimedWaitDelay"=30; "IRPStackSize"=32; "DefaultTTL"=64
        "KeepAliveTime"=30000; "KeepAliveInterval"=1000; "TCPInitialRtt"=300
        "TcpMaxDupAcks"=2; "EnablePMTUBHDetect"=0; "EnablePMTUDiscovery"=1
        "DisableTaskOffload"=0; "MaxHashTableSize"=65536; "MaxUserPort"=65534
        "MaxFreeTcbs"=65536; "TcpMaxSendFree"=65535; "SynAttackProtect"=0
        "EnableICMPRedirect"=0; "NumTcbTablePartitions"=4
    }
    foreach($k in $pVals.Keys){
        Save-Orig "BabyDek_Reg_$k" $pPath $k
        Set-RegValue $pPath $k $pVals[$k] | Out-Null
    }
    # Also set on Interfaces parent (best-effort; per-adapter keys vary)
    $ifRoot = "HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces"
    if(Test-Path $ifRoot){
        Get-ChildItem $ifRoot -EA SilentlyContinue | ForEach-Object {
            foreach($k in @("TcpAckFrequency","TCPNoDelay","TcpDelAckTicks","TCPTimedWaitDelay")){
                if($pVals.ContainsKey($k)){ Set-RegValue $_.PSPath $k $pVals[$k] | Out-Null }
            }
        }
    }
    Add-Log "BabyDek registry TCP parameters written" "#9B5DE5"
    $Global:AppliedKeys["BabyDek_RegParams"]=$true
}

