function Run-TscSyncEnhanced {
    Set-CurrentTask "BCD: tscsyncpolicy Enhanced"
    try {
        bcdedit /set tscsyncpolicy Enhanced 2>&1 | Out-Null
        bcdedit /set disabledynamictick yes 2>&1 | Out-Null
        bcdedit /set useplatformtick yes 2>&1 | Out-Null
        Add-Log "tscsyncpolicy=Enhanced + dynamic tick tweaks (reboot)" "#9B5DE5"
        $Global:AppliedKeys["SYS_TscSyncEnhanced"]=$true
    } catch { Add-Log "BCD tscsync failed: $_" "#EF4444" }
}

