MaxPendingRequests=32
[PoolSizes]
TxdStore=18000
DrawableStore=15000
FragInst=12000
VehicleStruct=10000
Ped=10000
[Settings]
AdaptiveStreaming=0
DisableDirectXOverlay=1
StreamingOnMainThread=1
UseAllCores=1
[Threads]
ThreadPriorityBoost=0
StreamingThreadPriority=0
MainThreadPriority=1
[Game]
DisableCustomLoadingScreen=1
StreamingUseAllPhysicalCores=1
DisableScriptHook=1
UseStreamingSystem=1
UseDirectStreaming=1
[Performance]
FPSLimit=0
DisableLoadingScreens=1
DisableTextureStreaming=0
ReduceBackgroundStreaming=1
EnableAsyncCompute=1
DisableTelemetry=1
DisableCrashUpload=1
[Streaming]
MaxLodScale=0.1
LodScale=0.1
PedLodBias=0
VehicleLodBias=0
WorldDetail=0
PopulationDensity=0
PopulationVariety=0
DistanceScaling=0
[Input]
